class ContractError(Exception):
    def __init__(self, code: str, detail: str = ""):
        super().__init__(f"{code}: {detail}" if detail else code)
        self.code = code
        self.detail = detail


def fail(code, detail=""):
    raise ContractError(code, detail)


def canonical(value):
    return (json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":")) + "\n").encode()


def digest(value):
    return hashlib.sha256(canonical(value)).hexdigest()


def sha(data):
    return hashlib.sha256(data).hexdigest()


def git(*args, cwd=ROOT, text=True):
    return subprocess.check_output(["git", *args], cwd=cwd, text=text)


def git_json(commit, path):
    return json.loads(git("show", f"{commit}:{path}"))


def accepted_catalog():
    """Reconstruct mapping authority identities directly from signed objects."""
    acceptance = git_json(ACCEPTANCE_COMMIT, ACCEPTANCE_PATH)
    renderer = git_json(RENDERER_COMMIT, RENDERER_PATH)
    impl = git_json(IMPL_COMMIT, IMPL_PATH)
    continuity = git_json(CONT_COMMIT, CONT_PATH)
    expected = {}
    records = {x["requirement_id"]: x for x in renderer["records"]}
    for item in acceptance["retained_contracts"]:
        rid = item["requirement_id"]
        expected["REQ-" + rid] = ("retained_requirement", records[rid]["contract_sha256"])
    contracts = acceptance["batch_1_contracts"] + acceptance["batch_2_contracts"] + acceptance["batch_3_contracts"]
    for contract in contracts:
        rid = contract["requirement_id"]
        expected["REQ-" + rid] = ("elaborated_requirement", contract["source_fingerprint"])
        for obligation in contract["obligation_mapping"]:
            expected[f"OBL-{rid}-{obligation['obligation_id']}"] = ("source_obligation", digest(obligation))
        for criterion in contract["acceptance_criteria"]:
            expected[f"CRT-{rid}-{criterion['criterion_id']}"] = ("source_criterion", digest(criterion))
    for clause in acceptance["decision_derived_acceptance_clauses"]:
        expected["ACL-" + clause["clause_id"]] = ("decision_clause", clause["authoritative_rule_fingerprint"])
    selected_payloads = {}
    for decision in impl["decisions"]:
        oid = IMPL_SELECTED[decision["decision_id"]]
        option = next(x for x in decision["options"] if x["option_id"] == oid)
        payload = {"decision_id": decision["decision_id"], "selected_option": option, "non_inferences": decision["non_inferences"]}
        mid = "IMPL-" + decision["decision_id"]
        expected[mid] = ("implementation_decision", digest(payload))
        selected_payloads[decision["decision_id"]] = digest(payload)
    continuity_payloads = {}
    for decision in continuity["decisions"]:
        oid = CONT_SELECTED[decision["decision_id"]]
        option = next(x for x in decision["options"] if x["option_id"] == oid)
        payload = {"decision_id": decision["decision_id"], "selected_option": option}
        continuity_payloads[decision["decision_id"]] = digest(payload)
    return expected, selected_payloads, continuity_payloads


def parse_markdown(raw: bytes):
    if not raw.endswith(b"\n") or raw.endswith(b"\n\n"):
        fail("MARKDOWN_EOF_INVALID")
    for line in raw.decode().splitlines():
        if line.rstrip() != line:
            fail("MARKDOWN_TRAILING_WHITESPACE")
    pattern = re.compile(r"<!-- C1_R2_SECTION:([a-z_]+) -->\n## \1\n\n```json\n(.*?)\n```", re.S)
    found = {}
    for name, value in pattern.findall(raw.decode()):
        if name in found:
            fail("MARKDOWN_SECTION_DUPLICATE", name)
        found[name] = json.loads(value)
    if set(found) != set(SECTIONS):
        fail("MARKDOWN_SECTION_INVENTORY_MISMATCH", str(sorted(set(SECTIONS) ^ set(found))))
    return found


def validate_locale(payload):
    locale = payload["design"]["locale"]
    option = locale["selected_option"]
    algorithm = option["algorithm"]
    if algorithm.get("priority") != "Sort by descending q-value, preserving original header order for ties.":
        fail("AMBIGUOUS_ACCEPT_LANGUAGE_ORDER")
    if algorithm.get("matching") != "Case-insensitive BCP47 canonical comparison with exact supported-tag equality only; no language-subtag truncation.":
        fail("UNAUTHORIZED_LOCALE_SUBTAG_FALLBACK")
    if algorithm.get("q_zero") != "q=0 ranges are explicitly unacceptable and never selected.":
        fail("Q_ZERO_LOCALE_SELECTED")
    fixtures = locale.get("fixtures", [])
    by_id = {x.get("fixture_id"): x for x in fixtures}
    expected = {
        "LOC-DUP-DIFFERENT-Q": ("fr-CA;q=0.4, fr-CA;q=0.9, en-US;q=0.8", "fr-CA"),
        "LOC-DUP-EQUAL-Q": ("fr-CA;q=0.8, fr-CA;q=0.8, en-US;q=0.7", "fr-CA"),
        "LOC-EQUAL-Q-ORDER": ("fr-CA;q=0.8, en-US;q=0.8", "fr-CA"),
        "LOC-MALFORMED-Q": ("fr-CA;q=bogus, en-US;q=0.7", "en-US"),
        "LOC-OUT-OF-RANGE-Q": ("fr-CA;q=1.5", "en-US"),
        "LOC-Q-ZERO": ("fr-CA;q=0, en-US;q=0.5", "en-US"),
        "LOC-WILDCARD": ("*;q=1", "en-US"),
        "LOC-UNSUPPORTED": ("zz-ZZ;q=1", "en-US"),
        "LOC-MISSING-HEADER": (None, "fr-CA"),
        "LOC-NO-SUBTAG-FALLBACK": ("en;q=1", "fr-CA"),
        "LOC-LIST-DETAIL-CONSISTENCY": ("fr-CA;q=1", "fr-CA"),
    }
    if set(by_id) != set(expected) or len(fixtures) != len(expected):
        fail("LOCALE_FIXTURE_COVERAGE_INCOMPLETE")
    for fid, (header, resolved) in expected.items():
        case = by_id[fid]
        if case.get("raw_accept_language") != header or case.get("expected_resolved_locale") != resolved:
            if fid.startswith("LOC-DUP"):
                fail("LOCALE_DUPLICATE_RANGE_POLICY_INVALID", fid)
            if fid == "LOC-EQUAL-Q-ORDER":
                fail("AMBIGUOUS_ACCEPT_LANGUAGE_ORDER", fid)
            if fid in {"LOC-MALFORMED-Q", "LOC-OUT-OF-RANGE-Q"}:
                fail("LOCALE_MALFORMED_Q_POLICY_INVALID", fid)
            if fid == "LOC-Q-ZERO":
                fail("Q_ZERO_LOCALE_SELECTED", fid)
            if fid == "LOC-NO-SUBTAG-FALLBACK":
                fail("UNAUTHORIZED_LOCALE_SUBTAG_FALLBACK", fid)
            fail("LOCALE_FIXTURE_SEMANTICS_INVALID", fid)
        if case.get("runtime_status") != "PLANNED_NOT_EXECUTED" or not case.get("api_observation") or not case.get("command_ids") or not case.get("isolation_cleanup"):
            fail("LOCALE_FIXTURE_EXECUTION_CONTRACT_INCOMPLETE", fid)
    if "browser" not in by_id["LOC-LIST-DETAIL-CONSISTENCY"].get("ui_observation", ""):
        fail("LOCALE_LIST_DETAIL_OBSERVATION_INCOMPLETE")


def validate_cursor(payload):
    cursor = payload["design"]["cursor_continuity"]
    fields = set(cursor["cursor_fields"])
    if "logical catalog revision" not in fields:
        fail("CURSOR_REVISION_BINDING_MISSING")
    if "storefront public identity" not in fields:
        fail("CURSOR_STOREFRONT_BINDING_MISSING")
    if "UTC evaluation instant" not in fields or "integrity tag" not in fields:
        fail("CURSOR_CONTEXT_OR_INTEGRITY_MISSING")
    boundary = cursor["request_boundary"]
    if "new PostgreSQL REPEATABLE READ transaction per page" not in boundary or "logical revision and evaluation instant provide continuity" not in boundary:
        fail("CROSS_REQUEST_REPEATABLE_READ_MISCLAIM")
    invariants = payload["design"]["data"]["revision_invariants"]
    if not any("no PostgreSQL snapshot spans requests" in x for x in invariants):
        fail("CROSS_REQUEST_REPEATABLE_READ_MISCLAIM")
    fixtures = " ".join(cursor["concurrent_fixtures"])
    for token in ["insert", "update", "publication", "price", "retirement/deletion", "cross-Storefront"]:
        if token not in fixtures:
            fail("CURSOR_CONCURRENT_FIXTURE_MISSING", token)


def validate_targeted_mappings(by_id):
    unknown = by_id.get("ACL-DEC003-UNKNOWN_SLUG")
    if not unknown or "404" not in json.dumps(unknown["expected_outcome"]) or "PRODUCT_NOT_FOUND" not in json.dumps(unknown["expected_outcome"]):
        fail("UNKNOWN_SLUG_PUBLIC_OUTCOME_MISMATCH")
    if any(x in json.dumps(unknown["expected_outcome"]).lower() for x in ["diagnostic", "internal reason"]):
        fail("UNKNOWN_SLUG_PUBLIC_OUTCOME_MISMATCH")
    publication = by_id.get("ACL-DEC001-PUBLICATION_VALIDATION_PASS")
    if not publication or not any(x.startswith("apps/api/") or x.startswith("database/") for x in publication["owner_paths"]):
        fail("PUBLICATION_VALIDATION_OWNER_IRRELEVANT")
    supplier = by_id.get("ACL-DEC002-NO_PUBLIC_SUPPLIER_REFERENCE")
    if not supplier or supplier["independent_observation"].get("expected_derived") is not False:
        fail("EXPECTED_DERIVED_OBSERVATION")
    non_schema = by_id.get("ACL-DEC002-NO_DATABASE_SCHEMA_DECISION")
    if not non_schema:
        fail("MAPPING_AUTHORITY_MISMATCH", "ACL-DEC002-NO_DATABASE_SCHEMA_DECISION")
    if "vs001:db:migrate" in non_schema.get("validation_command_ids", []) or non_schema.get("implementation_batch_ids") != ["B2"]:
        fail("DB_MIGRATE_NON_INFERENCE_OWNER")
    if any(path.startswith("database/migrations/") or path.startswith("apps/web/") for path in non_schema.get("owner_paths", [])):
        fail("DB_MIGRATE_NON_INFERENCE_OWNER")
    for mid in EXPECTED_MIGRATION_MAPPING_IDS:
        mapping = by_id.get(mid)
        if not mapping or mapping.get("implementation_batch_ids") != ["B1"] or "vs001:db:migrate" not in mapping.get("validation_command_ids", []):
            fail("DB_MIGRATE_BATCH_B1_MISSING", mid)


def validate_mappings(payload):
    mappings = payload["traceability_mappings"]
    ids = [x.get("mapping_id") for x in mappings]
    if len(mappings) != 211 or len(set(ids)) != 211:
        fail("TRACEABILITY_MAPPING_INVENTORY_MISMATCH")
    accepted, _, _ = accepted_catalog()
    if set(ids) != set(accepted):
        fail("TRACEABILITY_AUTHORITY_UNION_MISMATCH")
    by_id = {x["mapping_id"]: x for x in mappings}
    validate_targeted_mappings(by_id)
    for mid, mapping in by_id.items():
        mtype, fingerprint = accepted[mid]
        if mapping.get("mapping_type") != mtype or mapping.get("authority", {}).get("fingerprint") != fingerprint:
            fail("MAPPING_AUTHORITY_MISMATCH", mid)
        if mapping.get("runtime_evidence_status") != "NOT_EXECUTED" or mapping.get("implementation_authorized") is not False:
            fail("MAPPING_RUNTIME_OR_AUTHORIZATION_INVALID", mid)
        fixture = mapping.get("controlled_fixture", {})
        if not fixture.get("fixture_id") or mid not in fixture.get("fixture_id", "") or "never shared" not in fixture.get("isolation", ""):
            fail("UNCONTROLLED_MAPPING_FIXTURE", mid)
        owners = mapping.get("owner_paths", [])
        if not owners or any(not isinstance(x, str) for x in owners):
            fail("MAPPING_OWNER_INVALID", mid)
        observation = mapping.get("independent_observation", {})
        if observation.get("expected_derived") is not False or observation.get("expected_authority") == observation.get("observed_authority"):
            fail("EXPECTED_DERIVED_OBSERVATION", mid)
        cleanup = mapping.get("cleanup_contract", {})
        cleanup_text = json.dumps(cleanup)
        if mid not in cleanup_text or "zero owned residue" not in cleanup_text or "never retain" not in cleanup_text:
            fail("UNSAFE_MAPPING_CLEANUP", mid)
        if not mapping.get("validation_command_ids") or not set(mapping["validation_command_ids"]).issubset(FOCUSED):
            fail("MAPPING_COMMAND_BINDING_INVALID", mid)
        if len(mapping.get("implementation_batch_ids", [])) != 1:
            fail("MAPPING_BATCH_BINDING_INVALID", mid)
        if mid not in EXPECTED_MAPPING_HASHES:
            fail("FROZEN_MAPPING_ORACLE_MISSING", mid)
        if digest(mapping) != EXPECTED_MAPPING_HASHES[mid]:
            fail("MAPPING_SEMANTIC_FINGERPRINT_MISMATCH", mid)


def validate_bindings(payload):
    bindings = payload["decision_bindings"]
    if len(bindings) != 11 or len({x["binding_id"] for x in bindings}) != 11:
        fail("DECISION_BINDING_INVENTORY_MISMATCH")
    _, impl_payloads, cont_payloads = accepted_catalog()
    expected = {**impl_payloads, **cont_payloads}
    for binding in bindings:
        did = binding["decision_id"]
        selected = IMPL_SELECTED.get(did, CONT_SELECTED.get(did))
        if selected != binding.get("selected_option_id") or binding.get("authority", {}).get("fingerprint") != expected.get(did):
            fail("DECISION_BINDING_AUTHORITY_MISMATCH", did)
        owners = binding.get("owner_paths", [])
        layers = {x.split("/")[0] for x in owners}
        if len(owners) < 4 or len(layers) < 3:
            fail("CROSS_LAYER_DECISION_OWNER_INCOMPLETE", did)
        fixture = binding.get("controlled_fixtures", {})
        if not fixture.get("ownership_token") or not fixture.get("positive_authority_state") or not fixture.get("independent_control"):
            fail("GENERIC_DECISION_FIXTURE", did)
        if binding.get("runtime_evidence_status") != "NOT_EXECUTED" or binding.get("implementation_authorized") is not False:
            fail("DECISION_BINDING_RUNTIME_OR_AUTHORIZATION_INVALID", did)
        execution = EXPECTED_BINDING_EXECUTION.get(did)
        if execution is None:
            fail("DECISION_BINDING_EXPECTATION_MISSING", did)
        commands = binding.get("commands", [])
        batches = binding.get("batches", [])
        if set(commands) == FOCUSED:
            fail("DECISION_BINDING_ALL_FOCUSED_COMMANDS", did)
        if set(batches) == {f"B{x}" for x in range(1, 8)}:
            fail("DECISION_BINDING_ALL_BATCHES", did)
        missing_commands = set(execution["commands"]) - set(commands)
        extra_commands = set(commands) - set(execution["commands"])
        if missing_commands:
            fail("DECISION_BINDING_REQUIRED_COMMAND_MISSING", did + ":" + ",".join(sorted(missing_commands)))
        if extra_commands:
            fail("DECISION_BINDING_IRRELEVANT_COMMAND", did + ":" + ",".join(sorted(extra_commands)))
        if commands != execution["commands"]:
            fail("DECISION_BINDING_COMMAND_ORDER_INVALID", did)
        missing_batches = set(execution["batches"]) - set(batches)
        extra_batches = set(batches) - set(execution["batches"])
        if missing_batches:
            fail("DECISION_BINDING_REQUIRED_BATCH_MISSING", did + ":" + ",".join(sorted(missing_batches)))
        if extra_batches:
            fail("DECISION_BINDING_IRRELEVANT_BATCH", did + ":" + ",".join(sorted(extra_batches)))
        if batches != execution["batches"]:
            fail("DECISION_BINDING_BATCH_ORDER_INVALID", did)
        bid = binding["binding_id"]
        if bid not in EXPECTED_BINDING_HASHES or digest(binding) != EXPECTED_BINDING_HASHES[bid]:
            fail("DECISION_BINDING_FINGERPRINT_MISMATCH", bid)


def validate_commands_batches(payload):
    mappings = payload["traceability_mappings"]
    mids = {x["mapping_id"] for x in mappings}
    commands = payload["commands"]
    cids = [x["command_id"] for x in commands]
    if len(commands) != 22 or len(set(cids)) != 22:
        fail("COMMAND_INVENTORY_MISMATCH")
    inherited = {x["command_id"]: x for x in commands if x.get("command_class") == "INHERITED_COMMISSIONING_FOUNDATION_GATE"}
    if set(inherited) != set(EXPECTED_INHERITED):
        fail("INHERITED_COMMAND_INVENTORY_MISMATCH")
    accepted_scripts = git_json(COMMISSIONING_ACCEPTED, "package.json").get("scripts", {})
    for cid, (command_text, required_batches) in EXPECTED_INHERITED.items():
        command = inherited[cid]
        if command.get("command") != command_text or command.get("required_by_batches") != required_batches:
            fail("INHERITED_COMMAND_CLASSIFICATION_INVALID", cid)
        if command.get("acceptance_evidence") is not False:
            fail("FOUNDATION_COMMAND_FALSE_ACCEPTANCE_EVIDENCE", cid)
        if "mapping_ids" in command:
            fail("INHERITED_COMMAND_CLASSIFICATION_INVALID", cid)
        if not command.get("foundation_gate_ids") or not command.get("foundation_purpose") or not command.get("authority"):
            fail("INHERITED_COMMAND_CLASSIFICATION_INVALID", cid)
        script_name = cid.split(":", 1)[1]
        authority = command["authority"]
        if authority.get("accepted_commit") != COMMISSIONING_ACCEPTED or authority.get("git_path") != "package.json" or authority.get("script_name") != script_name or authority.get("accepted_script_definition") != accepted_scripts.get(script_name):
            fail("INHERITED_COMMAND_AUTHORITY_MISMATCH", cid)
    focused = {x["command_id"]: x for x in commands if x.get("command_class") == "FOCUSED_VS001_TRACEABILITY_COMMAND"}
    if set(focused) != FOCUSED:
        fail("FOCUSED_COMMAND_INVENTORY_MISMATCH")
    for cid, command in focused.items():
        refs = command.get("mapping_ids", [])
        if not refs:
            fail("FLOATING_FOCUSED_COMMAND", cid)
        if not set(refs).issubset(mids) or len(refs) != len(set(refs)):
            fail("COMMAND_MAPPING_BINDING_INVALID", cid)
        if command.get("real_process") is not True or command.get("success_exit") != 0 or not command.get("evidence_output") or not command.get("process_contract") or "cleanup" not in command:
            fail("COMMAND_EXECUTION_CONTRACT_INCOMPLETE", cid)
        expected_bindings = sorted("BIND-" + did for did, rule in EXPECTED_BINDING_EXECUTION.items() if cid in rule["commands"])
        if sorted(command.get("decision_binding_ids", [])) != expected_bindings:
            fail("COMMAND_DECISION_BINDING_RELEVANCE_MISMATCH", cid)
    migration = focused["vs001:db:migrate"]
    if migration.get("primary_batch_id") != "B1" or "B1" not in migration.get("owning_batches", []):
        fail("DB_MIGRATE_BATCH_B1_MISSING")
    migration_refs = set(migration.get("mapping_ids", []))
    if "ACL-DEC002-NO_DATABASE_SCHEMA_DECISION" in migration_refs:
        fail("DB_MIGRATE_NON_INFERENCE_OWNER")
    if migration_refs != EXPECTED_MIGRATION_MAPPING_IDS:
        fail("DB_MIGRATE_UNRELATED_MAPPING", str(sorted(migration_refs ^ EXPECTED_MIGRATION_MAPPING_IDS)))
    if "PostgreSQL" not in migration.get("evidence_output", "") or "browser" in migration.get("evidence_output", "").lower():
        fail("DB_MIGRATE_BROWSER_ONLY_EVIDENCE")
    for cid, command in {x["command_id"]: x for x in commands}.items():
        if cid not in EXPECTED_COMMAND_HASHES or digest(command) != EXPECTED_COMMAND_HASHES[cid]:
            fail("COMMAND_SEMANTIC_FINGERPRINT_MISMATCH", cid)
    for mapping in mappings:
        if not set(mapping["validation_command_ids"]).issubset(set(focused)):
            fail("MAPPING_COMMAND_BINDING_INVALID", mapping["mapping_id"])
    batches = payload["implementation_batches"]
    if [x["batch_id"] for x in batches] != [f"B{x}" for x in range(1, 8)]:
        fail("BATCH_INVENTORY_OR_ORDER_INVALID")
    all_refs = []
    all_paths = []
    for index, batch in enumerate(batches):
        expected_pre = [f"B{x}" for x in range(1, index + 1)]
        if batch.get("prerequisite_batch_ids") != expected_pre:
            fail("BATCH_DEPENDENCY_INVALID", batch["batch_id"])
        refs = batch.get("mapping_ids", [])
        if not refs or len(refs) != len(set(refs)) or not set(refs).issubset(mids):
            fail("BROAD_OR_INEXACT_BATCH_COVERAGE", batch["batch_id"])
        if refs != EXPECTED_BATCH_MAPPING_IDS.get(batch["batch_id"]):
            fail("BROAD_OR_INEXACT_BATCH_COVERAGE", batch["batch_id"])
        all_refs.extend(refs)
        paths = batch.get("allowed_paths", [])
        if set(paths) & set(all_paths):
            fail("BATCH_PATH_OWNERSHIP_OVERLAP", batch["batch_id"])
        all_paths.extend(paths)
        completion = batch.get("completion_gates", {})
        gates = {x["mapping_id"] for x in completion.get("mapping_gates", [])}
        if gates != set(refs):
            fail("BROAD_OR_INEXACT_BATCH_COVERAGE", batch["batch_id"])
        binding_ids = {"BIND-" + did for did, rule in EXPECTED_BINDING_EXECUTION.items() if batch["batch_id"] in rule["batches"]}
        if set(batch.get("decision_binding_ids", [])) != binding_ids:
            fail("BATCH_DECISION_BINDING_RELEVANCE_MISMATCH", batch["batch_id"])
        decision_gates = {x["binding_id"] for x in completion.get("decision_binding_gates", [])}
        if decision_gates != binding_ids:
            fail("BATCH_DECISION_GATE_MISMATCH", batch["batch_id"])
        expected_focused = {cid for cid, command in focused.items() if batch["batch_id"] in command.get("owning_batches", [])}
        if set(batch.get("focused_command_ids", [])) != expected_focused:
            fail("BATCH_FOCUSED_COMMAND_RELEVANCE_MISMATCH", batch["batch_id"])
        expected_inherited = {cid for cid, command in inherited.items() if batch["batch_id"] in command.get("required_by_batches", [])}
        if set(batch.get("inherited_foundation_gate_ids", [])) != expected_inherited:
            fail("BATCH_FOUNDATION_GATE_RELEVANCE_MISMATCH", batch["batch_id"])
        if batch["batch_id"] not in EXPECTED_BATCH_HASHES or digest(batch) != EXPECTED_BATCH_HASHES[batch["batch_id"]]:
            fail("BATCH_SEMANTIC_FINGERPRINT_MISMATCH", batch["batch_id"])
    if len(all_refs) != len(set(all_refs)) or set(all_refs) != mids:
        fail("BROAD_OR_INEXACT_BATCH_COVERAGE")
    distribution = payload.get("batch_distribution", {})
    current = [len(x["mapping_ids"]) for x in batches]
    if distribution.get("previous") != [19, 29, 30, 49, 6, 69, 9] or distribution.get("current") != current or not distribution.get("change_reason"):
        fail("BATCH_DISTRIBUTION_ACCOUNTING_INVALID")
    allowed = set(payload["design"]["path_policy"]["allowed"])
    if set(all_paths) != allowed:
        fail("BATCH_ALLOWED_PATH_UNION_MISMATCH", str(sorted(allowed - set(all_paths))))


def expected_sections(payload):
    return {
        "metadata": {k: payload[k] for k in ["candidate_id", "status", "approval", "runtime_evidence_status", "implementation_authorized", "next_gate", "accounting"]},
        "api": payload["design"]["api"], "data": payload["design"]["data"], "ui": payload["design"]["ui"],
        "security_observability": payload["design"]["security_observability"], "locale": payload["design"]["locale"],
        "cursor_continuity": payload["design"]["cursor_continuity"], "path_policy": payload["design"]["path_policy"],
        "decision_bindings": payload["decision_bindings"], "traceability_summary": payload["traceability_summary"],
        "traceability_catalog": payload["traceability_mappings"], "batches": payload["implementation_batches"],
        "commands": payload["commands"], "non_claims": payload["non_claims"],
    }


def validate_manifest(payload, manifest, root):
    if manifest.get("candidate_id") != payload["candidate_id"]:
        fail("MANIFEST_IDENTITY_MISMATCH")
    paths = {str(p.relative_to(root)): p for p in [root / x for x in FILES]}
    hashes = {name: sha(path.read_bytes()) for name, path in paths.items() if name != FILES[2]}
    if manifest.get("file_sha256_excluding_manifest") != hashes:
        fail("MANIFEST_FILE_HASH_MISMATCH")
    generated = [FILES[0], FILES[1]]
    aggregate = digest([{"path": x, "sha256": hashes[x]} for x in sorted(generated)])
    if manifest.get("generated_payload_aggregate") != aggregate:
        fail("MANIFEST_GENERATED_AGGREGATE_MISMATCH")
    if manifest.get("mapping_catalog_root") != digest(EXPECTED_MAPPING_HASHES):
        fail("MANIFEST_MAPPING_ROOT_MISMATCH")
    if manifest.get("decision_binding_root") != digest(EXPECTED_BINDING_HASHES):
        fail("MANIFEST_BINDING_ROOT_MISMATCH")
    if manifest.get("command_catalog_root") != digest(EXPECTED_COMMAND_HASHES):
        fail("MANIFEST_COMMAND_ROOT_MISMATCH")
    if manifest.get("batch_catalog_root") != digest(EXPECTED_BATCH_HASHES):
        fail("MANIFEST_BATCH_ROOT_MISMATCH")
    if manifest.get("staged_tree") != "DETACHED_HUMAN_GATE_VALUE" or manifest.get("git_content_aggregate") != "DETACHED_HUMAN_GATE_VALUE":
        fail("MANIFEST_SELF_REFERENCE_DOMAIN_INVALID")


def validate_git_boundary(root=ROOT):
    head = git("rev-parse", "HEAD", cwd=root).strip()
    if head == GOVERNING_HEAD:
        changed = set(filter(None, git("diff", "--name-only", "HEAD", cwd=root).splitlines()))
        changed |= set(filter(None, git("diff", "--cached", "--name-only", cwd=root).splitlines()))
        changed |= set(filter(None, git("ls-files", "--others", "--exclude-standard", cwd=root).splitlines()))
    else:
        parent = git("rev-parse", "HEAD^", cwd=root).strip()
        if parent != GOVERNING_HEAD:
            fail("CANDIDATE_LIFECYCLE_PARENT_MISMATCH", parent)
        changed = set(filter(None, git("diff", "--name-only", "HEAD^", "HEAD", cwd=root).splitlines()))
    if changed != set(FILES):
        fail("CONTRACT_ONLY_INVENTORY_MISMATCH", str(sorted(changed)))


def validate_payload(payload, markdown_raw=None, manifest=None, root=ROOT, check_git=False):
    if payload.get("candidate_id") != "V23-P2D-VS001-IMPLEMENTATION-CONTRACT-C1-R2" or payload.get("status") != "CANDIDATE" or payload.get("approval") != "PENDING_HUMAN_APPROVAL":
        fail("CANDIDATE_LIFECYCLE_STATE_INVALID")
    if payload.get("runtime_evidence_status") != "NOT_EXECUTED":
        fail("FALSE_RUNTIME_EVIDENCE_CLAIM")
    if payload.get("implementation_authorized") is not False:
        fail("IMPLEMENTATION_PREMATURELY_AUTHORIZED")
    expected_accounting = {"requirements": 25, "retained": 9, "elaborated": 16, "source_obligations": 21, "source_criteria": 32, "acceptance_clauses": 124, "implementation_decisions": 9, "continuity_decisions": 2, "traceability_mappings": 211, "decision_bindings": 11, "focused_commands": 12, "inherited_commands": 10, "classified_inherited_foundation_gates": 10, "unexplained_empty_bindings": 0, "floating_focused_commands": 0, "commands_falsely_claimed_as_acceptance_evidence": 0, "locale_controlled_cases": 11, "batches": 7, "implementation_changes": 0, "runtime_evidence_executed": 0}
    if payload.get("accounting") != expected_accounting:
        fail("ACCOUNTING_MISMATCH")
    validate_mappings(payload)
    validate_bindings(payload)
    validate_locale(payload)
    validate_cursor(payload)
    if digest(payload.get("design")) != EXPECTED_DESIGN_HASH:
        fail("DESIGN_SEMANTIC_FINGERPRINT_MISMATCH")
    validate_commands_batches(payload)
    if markdown_raw is not None:
        parsed = parse_markdown(markdown_raw)
        for name, expected in expected_sections(payload).items():
            if parsed.get(name) != expected:
                fail("MARKDOWN_SECTION_" + name.upper() + "_MISMATCH")
    if manifest is not None:
        validate_manifest(payload, manifest, root)
    if check_git:
        validate_git_boundary(root)
    return {"mappings": 211, "bindings": 11, "commands": 22, "batches": 7}


def main():
    payload = json.loads(JSON_PATH.read_text())
    manifest = json.loads(MANIFEST_PATH.read_text())
    result = validate_payload(payload, MD_PATH.read_bytes(), manifest, ROOT, True)
    print("VALID_PHASE_2D_VS001_IMPLEMENTATION_CONTRACT_C1_R2")
    print(json.dumps(result, sort_keys=True))


if __name__ == "__main__":
    try:
        main()
    except ContractError as error:
        print(error, file=sys.stderr)
        raise SystemExit(1)
